const JOST = "data:font/woff2;base64,";
const NSG = "data:font/woff2;base64,";
const NSERG = "data:font/woff2;base64,";

/* Local brand fonts (OFL). The preview has no network. Render once per artboard. */
export function BrandFonts() {
  const css = `
@font-face{font-family:"Jost";src:url(${JOST}) format("woff2");font-weight:300 700;font-display:swap}
@font-face{font-family:"Noto Sans Georgian";src:url(${NSG}) format("woff2");font-weight:300 900;font-display:swap}
@font-face{font-family:"Noto Serif Georgian";src:url(${NSERG}) format("woff2");font-weight:300 700;font-display:swap}`;
  return <style>{css}</style>;
}

type LogoTone = "color" | "plum" | "white";

/* Logo rebuilt from ლოგო.png geometry (2000×1204 source grid). */
export function Logo({
  tone = "color",
  className = "",
  title = "IG GROUP",
}: {
  tone?: LogoTone;
  className?: string;
  title?: string;
}) {
  const mark =
    tone === "white" ? "var(--color-ink-50)" : "var(--color-brand-800)";
  const word =
    tone === "color"
      ? "var(--color-accent-900)"
      : tone === "white"
        ? "var(--color-ink-50)"
        : "var(--color-brand-800)";
  return (
    <svg
      viewBox="320 230 1520 700"
      className={className}
      role="img"
      aria-label={title}
    >
      <rect x="343" y="268" width="62" height="624" fill={mark} />
      <path
        d="M1110.3 405.4 A297 297 0 1 0 1164.1 621.3"
        fill="none"
        stroke={mark}
        strokeWidth="63"
      />
      <rect x="1070" y="592" width="167" height="61" fill={mark} />
      <rect x="1251" y="592" width="557" height="26" fill={mark} />
      <text
        x="1266"
        y="826"
        fill={word}
        fontSize="205"
        textLength="519"
        lengthAdjust="spacingAndGlyphs"
        style={{ fontFamily: "Jost, sans-serif", fontWeight: 400 }}
      >
        group
      </text>
    </svg>
  );
}

/* The logo's G line, used as a section marker. */
export function Rule({
  className = "",
  tone = "brand",
}: {
  className?: string;
  tone?: "brand" | "accent" | "white";
}) {
  const bg =
    tone === "brand"
      ? "bg-brand-800"
      : tone === "accent"
        ? "bg-accent-900"
        : "bg-ink-50";
  return <span aria-hidden className={`block h-[2px] w-12 ${bg} ${className}`} />;
}

export function Eyebrow({
  children,
  num,
}: {
  children: React.ReactNode;
  num?: string;
}) {
  return (
    <span className="inline-flex items-center gap-2 rounded-pill bg-brand-50 border border-brand-100 px-3.5 py-1.5 text-[13px] font-medium text-brand-800">
      {num ? (
        <span style={latin} className="text-brand-400">
          {num}
        </span>
      ) : (
        <span className="w-1.5 h-1.5 rounded-full bg-accent-700" />
      )}
      {children}
    </span>
  );
}

export function Button({
  children,
  variant = "primary",
}: {
  children: React.ReactNode;
  variant?: "primary" | "secondary" | "ghost";
}) {
  const cls =
    variant === "primary"
      ? "bg-brand-800 text-ink-50 hover:bg-brand-700"
      : variant === "secondary"
        ? "border border-brand-800 text-brand-800 hover:bg-brand-50"
        : "text-brand-800 hover:text-brand-600";
  return (
    <button
      type="button"
      className={`inline-flex items-center gap-3 rounded-pill px-6 py-3.5 text-[15px] font-medium transition-colors ${cls}`}
    >
      {children}
      {variant !== "secondary" && (
        <svg width="18" height="18" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="1.5" aria-hidden>
          <path d="M5 12h14M13 6l6 6-6 6" />
        </svg>
      )}
    </button>
  );
}

